#!/usr/bin/env python3
"""Compiles capture-rules/*.js into Sources/IronPet/Capture/BundledCaptureRules.swift.

The rules are lookback's JavaScript rules, copied unchanged. Run this after editing one. A test fails when the
generated file is out of date.
"""
import pathlib
import sys

root = pathlib.Path(__file__).resolve().parent.parent
out = root / "Sources/IronPet/Capture/BundledCaptureRules.swift"

lines = [
    "// Generated by scripts/gen_capture_rules.py from capture-rules/*.js. Do not edit by hand.",
    "",
    "enum BundledCaptureRules {",
    "    /// The library every rule receives as its last argument.",
    "    static let context: String = #\"\"\"",
]
files = sorted(root.glob("capture-rules/*.js"))
rules = []
for path in files:
    text = path.read_text()
    if '"""' in text:
        sys.exit(f'{path}: contains """, which the generated Swift string cannot hold')
    body = text[:-1] if text.endswith("\n") else text
    if path.name == "_ctx.js":
        lines.append(body)
        lines.append('"""#')
    else:
        rules.append((path.stem, body))
lines += ["", "    /// Rule name and source, by name.", "    static let rules: [(name: String, source: String)] = ["]
for name, body in rules:
    lines.append(f'        ("{name}", #"""')
    lines.append(body)
    lines.append('"""#),')
lines += ["    ]", "}", ""]
out.write_text("\n".join(lines))
print(f"wrote {out.relative_to(root)} with {len(rules)} rules")
